import {test} from 'node:test';import assert from 'node:assert/strict';import {finalResultsView,podiumRevealOrder,PODIUM_STEP_MS} from '../src/presentation/final-results';import {OutbreakRules} from '../src/game/outbreak';import {FreezeRules,FREEZE} from '../src/game/freeze-tag';import {ClassicRules,CLASSIC} from '../src/game/classic-tag';import {Connection} from '../src/network/client';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
for(const mode of['poison','freeze','classic'])test(mode+': only the completed final round presents final totals and champions directly',()=>{const order=[0,1,2],r=mode==='freeze'?new FreezeRules(order,0,FREEZE):mode==='classic'?new ClassicRules(order,0,CLASSIC):new OutbreakRules(order,0);r.phase='round-results';r.totals=[30,40,40];let raw=r.view(10);assert.equal(finalResultsView(raw),raw);r.round=2;raw=r.view(10);const before=JSON.stringify(raw),display=finalResultsView(raw)!;assert.equal(display.phase,'match-results');assert.deepEqual(display.matchWinners,[1,2]);assert.equal(display.players,raw.players);assert.equal(JSON.stringify(raw),before);assert.equal(r.phase,'round-results');r.phase='match-results';raw=r.view(10);assert.equal(finalResultsView(raw),raw);assert.equal(finalResultsView(undefined),undefined);});
test('podium reveals each player once in descending place, keeping all shared winners last',()=>{assert.equal(PODIUM_STEP_MS,850);assert.deepEqual(podiumRevealOrder([{rank:1,slot:0},{rank:2,slot:1},{rank:3,slot:2},{rank:4,slot:3}]),[2,1,0]);assert.deepEqual(podiumRevealOrder([{rank:1,slot:0},{rank:1,slot:1},{rank:3,slot:2}]),[2,0,1]);assert.deepEqual(podiumRevealOrder(Array.from({length:8},(_,slot)=>({slot,rank:1}))),[0,1,2,3,4,5,6,7]);});
test('Return to Lobby completes the existing host-authorized final handoff in ordered messages',()=>{const sent:string[]=[],stub={status:'connected',outbreak:{phase:'round-results',round:2,roundCount:2},room:{send:(type:string)=>sent.push(type)}};Connection.prototype.returnLobby.call(stub as any);assert.deepEqual(sent,['next-round','return-lobby']);sent.length=0;stub.outbreak.phase='match-results';Connection.prototype.returnLobby.call(stub as any);assert.deepEqual(sent,['return-lobby']);sent.length=0;stub.status='Disconnected.';Connection.prototype.returnLobby.call(stub as any);assert.deepEqual(sent,[]);});
test('candidate changes presentation only; approved CPU, physics, arenas, modifiers and server remain exact',()=>{const m=JSON.parse(readFileSync('docs/final-podium-preservation.json','utf8')),h=(v:any)=>createHash('sha256').update(v).digest('hex');for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(h(r.original),r.beforeSha256,p);assert.equal(h(readFileSync(p)),r.afterSha256,p);}for(const[p,hash]of Object.entries(m.protected))assert.equal(h(readFileSync(p)),hash,p);});

